-- GOVERNED MIGRATION-HISTORY RECOVERY.
-- This filename preserves a production ledger version for clean replay.
-- Production history is never rewritten; live hashes remain in the recovery manifest.
-- Semantic recovery of the provider-recorded SQL payload; comments and terminal newline may differ.

create or replace function public.projectos_ingest_product_signal(p_organization_id uuid,p_signal jsonb) returns jsonb language plpgsql security definer set search_path=public,private,auth,pg_temp as $$ declare v_product_key text;v_event_name text;v_environment text;v_properties jsonb;v_allowed text[];v_inserted uuid;begin if auth.role()<>'service_role' then raise exception 'projectos_forbidden';end if;if jsonb_typeof(p_signal)<>'object' then raise exception 'invalid_payload';end if;v_product_key:=private.projectos_canonical_product_key(coalesce(p_signal->>'product_key',p_signal->>'app'));if v_product_key is null or v_product_key='banatao_systems' then raise exception 'unrecognized_product';end if;v_event_name:=nullif(trim(p_signal->>'event_name'),'');if v_event_name is null or length(v_event_name)>160 then raise exception 'invalid_event_name';end if;select allowed_properties into v_allowed from private.projectos_event_contracts where organization_id=p_organization_id and product_key=v_product_key and event_name=v_event_name and active;if v_allowed is null then raise exception 'event_not_allowed';end if;v_properties:=coalesce(p_signal->'properties','{}'::jsonb);if jsonb_typeof(v_properties)<>'object' or octet_length(v_properties::text)>16384 then raise exception 'invalid_properties';end if;if exists(select 1 from jsonb_object_keys(v_properties) k where not(k=any(v_allowed) or k=any(array['product_key','app','privacy_tier','source_repo']::text[]))) then raise exception 'property_not_allowed';end if;v_environment:=coalesce(nullif(p_signal->>'environment',''),'unknown');insert into private.projectos_product_signals(organization_id,product_key,event_name,occurred_at,environment,privacy_tier,release_sha,app_version,deployment_id,anonymous_actor_hash,properties,schema_version,dedupe_key) values(p_organization_id,v_product_key,v_event_name,coalesce((p_signal->>'occurred_at')::timestamptz,now()),v_environment,coalesce(nullif(p_signal->>'privacy_tier',''),'aggregate_only'),nullif(p_signal->>'release_sha',''),nullif(p_signal->>'app_version',''),nullif(p_signal->>'deployment_id',''),nullif(p_signal->>'anonymous_actor_hash',''),v_properties,coalesce((p_signal->>'schema_version')::integer,1),p_signal->>'dedupe_key') on conflict(organization_id,dedupe_key) do nothing returning id into v_inserted;return jsonb_build_object('status',case when v_inserted is null then 'duplicate' else 'accepted' end,'id',v_inserted,'product_key',v_product_key,'learnable',v_environment='production');exception when invalid_text_representation or datetime_field_overflow or not_null_violation or check_violation then raise exception 'invalid_payload';end;$$;
create or replace function public.projectos_get_product_intelligence_context(p_organization_id uuid,p_product_key text,p_days integer default 30) returns jsonb language plpgsql security definer set search_path=public,private,auth,pg_temp as $$ declare v_product_key text;v_since timestamptz;begin if auth.role()<>'service_role' and not private.is_org_member(p_organization_id) then raise exception 'projectos_forbidden';end if;v_product_key:=private.projectos_canonical_product_key(p_product_key);if v_product_key is null then return null;end if;v_since:=now()-(greatest(1,least(coalesce(p_days,30),365))||' days')::interval;return jsonb_build_object('product',(select to_jsonb(r) from private.projectos_product_registry r where r.organization_id=p_organization_id and r.product_key=v_product_key),'metrics',coalesce((select jsonb_agg(to_jsonb(m) order by metric_day desc,event_name) from(select date_trunc('day',occurred_at) metric_day,event_name,count(*) value,count(distinct anonymous_actor_hash) unique_actors,min(occurred_at) first_seen_at,max(occurred_at) last_seen_at from private.projectos_product_signals where organization_id=p_organization_id and product_key=v_product_key and learnable and occurred_at>=v_since group by date_trunc('day',occurred_at),event_name order by metric_day desc,event_name limit 500)m),'[]'::jsonb),'observations',coalesce((select jsonb_agg(to_jsonb(o) order by confidence desc,valid_from desc) from(select id,observation_type,summary,confidence,evidence,status,valid_from,valid_until,created_by,updated_at from private.projectos_product_observations where organization_id=p_organization_id and product_key=v_product_key and status='active' order by confidence desc,valid_from desc limit 50)o),'[]'::jsonb),'recommendations',coalesce((select jsonb_agg(to_jsonb(r) order by priority desc,confidence desc,updated_at desc) from(select id,recommendation_key,recommendation,rationale,expected_metric,baseline_value,target_value,confidence,priority,status,implementation_ref,measured_value,outcome_summary,created_at,updated_at from private.projectos_product_recommendations where organization_id=p_organization_id and product_key=v_product_key order by priority desc,confidence desc,updated_at desc limit 50)r),'[]'::jsonb),'learningFeedback',coalesce((select jsonb_object_agg(status,total) from(select status,count(*) total from private.projectos_product_recommendations where organization_id=p_organization_id and product_key=v_product_key group by status)s),'{}'::jsonb),'since',v_since);end;$$;
create or replace function public.projectos_record_product_observation(p_organization_id uuid,p_observation jsonb) returns jsonb language plpgsql security definer set search_path=public,private,auth,pg_temp as $$ declare v_id uuid;v_key text;begin if auth.role()<>'service_role' and not private.is_org_member(p_organization_id) then raise exception 'projectos_forbidden';end if;v_key:=private.projectos_canonical_product_key(p_observation->>'product_key');if v_key is null or v_key='banatao_systems' then raise exception 'unrecognized_product';end if;insert into private.projectos_product_observations(organization_id,product_key,observation_type,summary,confidence,evidence,created_by) values(p_organization_id,v_key,p_observation->>'observation_type',p_observation->>'summary',coalesce(nullif(p_observation->>'confidence','')::numeric,.5),coalesce(p_observation->'evidence','[]'::jsonb),coalesce(nullif(p_observation->>'created_by',''),'pandoras_box')) returning id into v_id;return jsonb_build_object('id',v_id,'product_key',v_key,'status','active');end;$$;
create or replace function public.projectos_record_product_recommendation(p_organization_id uuid,p_recommendation jsonb) returns jsonb language plpgsql security definer set search_path=public,private,auth,pg_temp as $$ declare v_id uuid;v_key text;begin if auth.role()<>'service_role' and not private.is_org_member(p_organization_id) then raise exception 'projectos_forbidden';end if;v_key:=private.projectos_canonical_product_key(p_recommendation->>'product_key');if v_key is null or v_key='banatao_systems' then raise exception 'unrecognized_product';end if;insert into private.projectos_product_recommendations(organization_id,product_key,recommendation_key,recommendation,rationale,expected_metric,baseline_value,target_value,confidence,priority,source_observation_ids) values(p_organization_id,v_key,p_recommendation->>'recommendation_key',p_recommendation->>'recommendation',p_recommendation->>'rationale',nullif(p_recommendation->>'expected_metric',''),nullif(p_recommendation->>'baseline_value','')::numeric,nullif(p_recommendation->>'target_value','')::numeric,coalesce(nullif(p_recommendation->>'confidence','')::numeric,.5),coalesce(nullif(p_recommendation->>'priority','')::integer,50),coalesce(array(select jsonb_array_elements_text(coalesce(p_recommendation->'source_observation_ids','[]'::jsonb))::uuid),'{}'::uuid[])) on conflict(organization_id,product_key,recommendation_key) do update set recommendation=excluded.recommendation,rationale=excluded.rationale,expected_metric=excluded.expected_metric,baseline_value=excluded.baseline_value,target_value=excluded.target_value,confidence=excluded.confidence,priority=excluded.priority,source_observation_ids=excluded.source_observation_ids,updated_at=now() returning id into v_id;return jsonb_build_object('id',v_id,'product_key',v_key,'status','proposed');end;$$;
create or replace function public.projectos_record_product_recommendation_outcome(p_organization_id uuid,p_outcome jsonb) returns jsonb language plpgsql security definer set search_path=public,private,auth,pg_temp as $$ declare v_row private.projectos_product_recommendations%rowtype;begin if auth.role()<>'service_role' and not private.is_org_member(p_organization_id) then raise exception 'projectos_forbidden';end if;update private.projectos_product_recommendations set status=p_outcome->>'status',implementation_ref=coalesce(nullif(p_outcome->>'implementation_ref',''),implementation_ref),measured_value=coalesce(nullif(p_outcome->>'measured_value','')::numeric,measured_value),outcome_summary=coalesce(nullif(p_outcome->>'outcome_summary',''),outcome_summary),updated_at=now() where organization_id=p_organization_id and id=(p_outcome->>'recommendation_id')::uuid returning * into v_row;if v_row.id is null then raise exception 'recommendation_not_found';end if;return jsonb_build_object('id',v_row.id,'product_key',v_row.product_key,'status',v_row.status,'measured_value',v_row.measured_value);end;$$;
revoke all on function public.projectos_ingest_product_signal(uuid,jsonb) from public,anon,authenticated;revoke all on function public.projectos_get_product_intelligence_context(uuid,text,integer) from public,anon;revoke all on function public.projectos_record_product_observation(uuid,jsonb) from public,anon;revoke all on function public.projectos_record_product_recommendation(uuid,jsonb) from public,anon;revoke all on function public.projectos_record_product_recommendation_outcome(uuid,jsonb) from public,anon;grant execute on function public.projectos_ingest_product_signal(uuid,jsonb) to service_role;grant execute on function public.projectos_get_product_intelligence_context(uuid,text,integer) to authenticated,service_role;grant execute on function public.projectos_record_product_observation(uuid,jsonb) to authenticated,service_role;grant execute on function public.projectos_record_product_recommendation(uuid,jsonb) to authenticated,service_role;grant execute on function public.projectos_record_product_recommendation_outcome(uuid,jsonb) to authenticated,service_role;
